\label{def:locally-dense-lat}
For $p \geq 1$ and $n, N \in \ensuremath{\mathbb{Z}}^+$, a \emph{$(p, n, N)$-exact locally dense lattice} consists of a lattice $\mathcal{L} \subset \ensuremath{\mathbb{R}}^m$ of rank $n$ and a target vector $\bm{t} \in \ensuremath{\mathbb{R}}^m \setminus \mathcal{L}$ satisfying the following properties.
\begin{enumerate}    \item (Many closest vectors.) $|\{\bm{x} \in \mathcal{L} : \|\bm{x} - \bm{t}\|_p = \operatorname{dist}_p(\bm{t}, \mathcal{L})\}| \geq N$. 
    \item \label{item:distance_less_than_lambda1} (Distance to $\bm{t}$ at most $\lambda_1$.) $\operatorname{dist}_p(\bm{t}, \mathcal{L}) \le \lambda_1^{(p)}(\mathcal{L})$.
    \item \label{local-dense-item-three} (Distance of integer multiples $k\bm{t}$.) For every integer $k$, either $k\bm{t} \in \mathcal{L}$ or $\operatorname{dist}_p(\bm{t}, \mathcal{L})\le \operatorname{dist}_p(k\bm{t},\mathcal{L})$. 

\end{enumerate}

\label{def:Hadamard}
    Let $H_1=[1]$. For $m\ge 2$ a power of 2, the Hadamard matrix $H_m$ is recursively defined as
   \[H_{m}=
\begin{pmatrix}
H_{m/2} & H_{m/2} \\
H_{m/2} & -H_{m/2}
\end{pmatrix}.
    \]

\label{fact: Hadamard}
    $H_m\in\{\pm 1\}^{m\times m}$ satisfies $H_m^\top H_m=m\bm{I}_m$, and 
    \[
    \|H_m\bm{e}_i\|_p=m^{1/p}
    \]for any $p \geq 1$ and $1\le i\le m$, where $\bm{e}_i$ is the $i$th standard basis vector.

\label{def:craig}
    For an odd prime $q$ and a positive integer $m$, the \emph{Craig lattice} $A_{q-1}^{(m)}$ is
    \[
A_{q-1}^{(m)}
:=
\set*{
\bm{x}\in\ensuremath{\mathbb{Z}}^q :
\sum_{i=1}^q x_i = 0 \quad\text{and}\quad 
\sum_{i=1}^q i^j \cdot x_i \equiv 0 \ (\mathrm{mod}\ q) \text{ for $j=1,\ldots,m-1$}} \ \text{.}
\]

\label{def:RS}
For an odd prime $q$ and an integer $1 \leq m \leq q$, the \emph{Reed-Solomon lattice} $\mathcal{L}_{q,m}$ is
\[
\mathcal{L}_{q,m} :=
\set*{
\bm{x}\in\ensuremath{\mathbb{Z}}^q :


\sum_{i=1}^q i^j \cdot x_i \equiv 0 \ (\mathrm{mod}\ q) \text{ for $j=0,\ldots,m-1$}} \ \text{.}



\]

\label{rmk:padding}
We can remove the restriction of~\cref{cor:craig kn} to prime $q$ by a standard padding argument. Suppose that, for every sufficiently large prime $q$, we have constructed a rank $q$ lattice $\mathcal{L}$ satisfying $\kappa_p(\mathcal{L})\ge \Omega(e^{\sqrt q}q^{3/4})$ (note $A_{q-1}^{(m)}+\ensuremath{\mathbb{Z}}\bm{t}$ has rank $q$). For any $n\ge q$, we can pad $\mathcal{L}$ into a rank $n$ lattice $\mathcal{L}'$ in a way that preserves relevant shortest vectors (e.g., adding long vectors orthogonal to $\mathcal{L}$). Hence $\kappa_p(n)\ge \kappa_p(\mathcal{L}') = \kappa_p(\mathcal{L})$.
By the prime number theorem, there always exists a prime $q$ with $n-o(n) < q \leq n$, and applying this construction yields 
\[
\kappa_p(n) \geq \Omega(e^{\sqrt{q}}) > e^{\sqrt{n} - o(\sqrt{n})} \ \text{.}
\]

\label{cor:refinement of wan}
    Fix $p\ge 1$, and take $k=\lfloor\alpha q^{1/4}/2\rfloor$ for some $0<\alpha<1$. Let $\bm{y} = (1,\dots,1,0,\dots,0)^\top$ be the binary vector in $\ensuremath{\mathbb{Z}}^q$ with Hamming weight $2k$. For all sufficiently large primes $q$, we have
  $|S_2(\bm{y},2k)|\ge 2^{\Omega(q^{1/4}\log q)}$, where $S_2$ is as defined in \cref{thm:locally dense construction}.

\label{thm: new G/A for Zn}
For any $p\ge 1$, and $\bm{t} := (\frac12,\frac12,\dots,\frac12)^\top\in\ensuremath{\mathbb{R}}^n$, we have
    \[
    \frac{G(\ensuremath{\mathbb{Z}}^n,\bm{t},n^{1/p}/2)}{A(\ensuremath{\mathbb{Z}}^n,\bm{t},n^{1/p}/2)}\ge \alpha_{p,1}^n \ \text{.}  
    \]

\label{thm:large p}
  Using the same $\bm{t},\alpha_{p,1}$ as~\cref{thm: new G/A for Zn}, when $p>p_0$ where $p_0 \approx 2.1397$ is defined in~\cref{thm:ball_point_count}, we have $\alpha_{p,1}>1$.

  In particular, there exists a sublattice $\mathcal{L}'\subseteq \ensuremath{\mathbb{Z}}^n$  and $ \bm{t}'\in\ensuremath{\mathbb{R}}^n$ such that $(\mathcal{L}',\bm{t}')$ is $(p,n,\Omega(\alpha_{p,1}^n))$-exact locally dense, and $\kappa_p(\mathcal{L}'+\ensuremath{\mathbb{Z}}\bm{t}')\ge\Omega(\alpha_{p,1}^n)= 2^{\Omega(n)}$.

\label{thm: general G and A}
  Fix any $p>2$, constant $k\ge 0$ and $m=2^k$. Let $\mathcal{M}_m=H_mD_m,\bm{t} = (1,\dots,1)^\top\in\ensuremath{\mathbb{Z}}^{m}$. For $\ell>0$, it holds that
$$\frac{G(\mathcal{M}_m^\ell,\bm{t}^\ell,(m\ell)^{1/p})}{A(\mathcal{M}_m^\ell,\bm{t}^\ell,(m\ell)^{1/p})}\ge \left(\frac{2m}{\min_{\tau>0} \, e^{\tau m} \cdot \Theta_p(\mathcal{M}_m,\tau)}\right)^\ell \ \text{.}$$

\label{lem:chosen tau bound}
   For any $p > 2$ and $m \geq 2$ a power of two, we have
   \[
   \alpha_{p,m}^m :=\frac{2m}{\min_{\tau>0} \, e^{\tau m}\Theta_p(\mathcal{M}_m,\tau)} \ge \frac{2m^{1-\mu}}{9} \ \text{,}
   \]
   where $\mu := 2^{1 - p/2} < 1$.

\label{lem: short vec not in qL}
For a lattice $\mathcal{L}$, $p\ge 1$ and $r>0$, if $\bm{0}\ne \bm{y}\in q\mathcal{L}$ and $\|\bm{y}\|_p\le r$, then we have 
$$N^o_p(\mathcal{L},r)\ge 2q-1.$$

\label{lem: equal norm not independent}
For a lattice $\mathcal{L}$, $p\ge 1$, $r>0$, and lattice vectors $\bm{v}, \bm{u} \in \mathcal{L}$ with $\|\bm{v}\|_p = \|\bm{u}\|_p =r$ and $\bm{v} \neq \pm \bm{u}$. Let $q\ge 3$ be an odd integer. If $\bm{v}\equiv k\bm{u}\pmod{q\mathcal{L}}$ for some integer $k$, then 
$$N^o_p(\mathcal{L},r)\ge q.$$

\label{lem:new-KN-to-LDL}
For any $p \geq 1$ and lattice $\mathcal{L}$ of rank $n$, there exists an index-two sublattice $\mathcal{L}' \subsetneq \mathcal{L}$ of $\mathcal{L}$ and vector $\bm{t} \in \mathcal{L} \setminus \mathcal{L}'$ such that $(\mathcal{L}', \bm{t})$ is a $(p, n, N)$-exact locally dense lattice for $N > \kappa_p(\mathcal{L})/2$.
In particular, for every $p \geq 1$ and $n \in \ensuremath{\mathbb{Z}}^+$ there exists a $(p, n, N)$-exact locally dense lattice for $N > \kappa_p(n)/2$.
